import { parseJson } from './parse.ts';
// parseJson returns unknown. Prove it is a string before indexing it.
export function firstChar(text: string): string {
  const raw = parseJson(text);
  return raw[0];
}

export function parseJson(text: string): unknown {
  return JSON.parse(text) as unknown;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { firstChar } from '../src/app.ts';
test('first char of a JSON string', () => { assert.equal(firstChar('"hello"'), 'h'); });
test('non-string JSON gives empty', () => { assert.equal(firstChar('42'), ''); });

