import { assertNever, type LabEvent } from './event.ts';
// 'booked' is not handled, so the value reaching assertNever is not `never`.
export function label(e: LabEvent): string {
  switch (e.kind) {
    case 'opened': return 'open';
    case 'closed': return 'shut';
    default: return assertNever(e);
  }
}

export type LabEvent =
  | { kind: 'opened' }
  | { kind: 'closed' }
  | { kind: 'booked' };
export function assertNever(x: never): never {
  throw new Error('unhandled event: ' + JSON.stringify(x));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { label } from '../src/app.ts';
test('labels each event', () => {
  assert.equal(label({ kind: 'opened' }), 'open');
  assert.equal(label({ kind: 'closed' }), 'shut');
  assert.equal(label({ kind: 'booked' }), 'taken');
});

